  "required": [
    "text",
    "delay"
  ]
}

{
  "type": "object",
  "properties": {
    "questions": {
      "type": "array",
      "description": "Questions to ask the user (at least one)",
      "items": {
        "type": "object",
        "properties": {
          "question": {
            "type": "string",
            "description": "Question text shown to the user"
