      File('$stubDir/log').writeAsStringSync('');
      final gh = File('$stubDir/bin/gh');
      gh.writeAsStringSync('''
#!/usr/bin/env bash
echo "\$*" >> "\$GH_LOG_FILE"
case "\$1 \$2" in
  "issue list"*)
    if [[ "\$*" == *"--label store-appearance-check"* ]]; then cat "\$GH_STUB_DIR/open_stubs.json"
