      );
      File('$stubDir/summarized.txt').writeAsStringSync(summarizedBodies);
      File('$stubDir/log').writeAsStringSync('');
      final gh = File('$stubDir/bin/gh');
      gh.writeAsStringSync('''
#!/usr/bin/env bash
echo "\$*" >> "\$GH_LOG_FILE"
case "\$1 \$2" in
