    if [[ "\$*" == *"--label store-appearance-check"* ]]; then cat "\$GH_STUB_DIR/open_stubs.json"
    else cat "\$GH_STUB_DIR/publish_stubs.json"; fi
    exit 0 ;;
  "issue view"*) cat "\$GH_STUB_DIR/summarized.txt"; exit 0 ;;
