      reason: 'the green summary lands on the day\'s publish stub',
    );
    expect(log.where((l) => l.contains('issue comment 8')).length, 1);
    expect(
      File('$stubDir/last-body.md').readAsStringSync(),
      contains('Store appearance check — all green'),
