            }
            return serveFixture(
              req,
              play == 'present'
                  ? 'play_track_present.json'
                  : 'play_track_absent.json',
            );
          }
        }
        if (path.startsWith('/pubdev/packages/')) {
          if (pubdev == 'error') {
            await serveJson(req, 'backend error (fixture)', 500);
            return;
          }
          return serveFixture(
            req,
            pubdev == 'present'
                ? 'pubdev_package_present.json'
                : 'pubdev_package_absent.json',
          );
