          if (path.endsWith('/edits/EDIT-1')) {
            req.response.statusCode = 204;
            await req.response.close();
            return;
          }
          if (path.endsWith('/tracks/beta')) {
            if (play == 'notrack') {
              await serveJson(req, {
                "error": {"code": 404, "message": "track empty (fixture)"},
              }, 404);
              return;
