    test(
      'fastlane processing wait is untouched (upload-owned, not the custom wait)',
      () {
        expect(fastfile, contains('skip_waiting_for_build_processing: false'));
        expect(fastfile, contains('TESTFLIGHT_WAIT_TIMEOUT_SECONDS'));
