        if (path == '/play-token') {
          final body = await utf8.decoder.bind(req).join();
          capturedGrants.add(body);
          await serveJson(req, {"access_token": "[REDACTED:Sensitive Value]"});
          return;
        }
        if (path.startsWith('/play/')) {
          if (play == 'error') {
            await serveJson(req, {
              "error": {"code": 500, "message": "backend error (fixture)"},
            }, 500);
